def dinheiro(v):
    try:
        n = float(v or 0)
    except:
        n = 0
    s = f"{n:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"R$ {s}"

def normaliza_placa(v):
    return re.sub(r"[^A-Za-z0-9]", "", str(v or "")).upper().strip()

def normaliza_cnpj(v):
    t = str(v or "").strip()
    if not t or t.lower()=="nan": return ""
    if t.upper()=="N/C": return "N/C"
    d = re.sub(r"\D", "", t)
    if len(d)==14:
        return f"{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:]}"
    return t.upper()

def parse_valor(v):
    if v is None: return 0.0
    try:
        if pd.isna(v): return 0.0
    except: pass
    if isinstance(v,(int,float)): return float(v)
    t = str(v).strip().upper().replace("R$","").replace(" ","")
    t = re.sub(r"[^0-9,.\-]", "", t)
    if t in ("","-",",","."): return 0.0
    if "," in t and "." in t:
        if t.rfind(",") > t.rfind("."):
            t = t.replace(".","").replace(",",".")
        else:
            t = t.replace(",","")
    elif "," in t:
        t = t.replace(",",".")
    try: return float(t)
    except: return 0.0

def tipo_automatico(texto):
    t = str(texto or "").lower()
    regras = [
        ("Pneus", ["pneu","alinh","balance","cambagem","borrachar"]),
        ("Elétrica", ["bateria","alternador","motor de partida","farol","lampada","lâmpada","chicote","fusivel","fusível","eletric"]),
        ("Funilaria", ["funilar","pintura","lataria","parachoque","para-choque","martelinho"]),
        ("Documentação", ["licenciamento","document","ipva","taxa","antt","detra"]),
        ("Revisão", ["revisão","revisao","check-up","check up"]),
        ("Preventiva", ["óleo","oleo","filtro","correia","fluido","limpeza","higien","lubrifica","prevent"]),
        ("Corretiva", ["reparo","conserto","troca","vazamento","quebrado","quebra","falha","defeito","mecân","mecan"]),
    ]
    for nome, termos in regras:
        if any(x in t for x in termos):
            return nome
    return "Outros"

def excel_bytes(df, aba="Relatorio"):
    bio = BytesIO()
    with pd.ExcelWriter(bio, engine="openpyxl") as wr:
        df.to_excel(wr,index=False,sheet_name=aba[:31])
    return bio.getvalue()

def _pdf_escape(s):
    s = str(s or "").replace("\\","\\\\").replace("(","\\(").replace(")","\\)")
    return s.encode("cp1252",errors="replace").decode("latin-1")

def pdf_resumo(rel, mes_nome, ano):
    W,H=595,842
    total=float(rel["valor"].sum()) if not rel.empty else 0
    qtd=len(rel)
    placas=rel["placa"].nunique() if not rel.empty else 0
    tipos=rel["tipo_manutencao"].nunique() if not rel.empty else 0
    por_placa=(rel.groupby("placa",as_index=False)["valor"].sum()
               .sort_values("valor",ascending=False)) if not rel.empty else pd.DataFrame(columns=["placa","valor"])
    cmds=[]
    def txt(x,y,s,size=10,b=False):
        f="F2" if b else "F1"
        cmds.append(f"BT /{f} {size} Tf 1 0 0 1 {x} {y} Tm ({_pdf_escape(s)}) Tj ET")
    def line(x1,y1,x2,y2,w=.5): cmds.append(f"{w} w {x1} {y1} m {x2} {y2} l S")
    def rect(x,y,w,h,fill=False): cmds.append(f"{x} {y} {w} {h} re {'f' if fill else 'S'}")
    cmds.append("0 0 0 rg"); rect(0,745,W,97,True); cmds.append("1 1 1 rg")
    txt(42,798,"GDS LOGISTICA",11,True); txt(42,775,"MANUTENCAO DE VEICULOS",21,True)
    txt(42,754,f"Resumo mensal - {mes_nome}/{ano}",11)
    cmds.append("0 0 0 rg"); txt(42,707,"RESUMO DO PERIODO",14,True); line(42,697,553,697)
    vals=[("TOTAL GASTO",dinheiro(total)),("MANUTENCOES",qtd),("PLACAS",placas),("TIPOS",tipos)]
    xs=[42,173,304,435]
    for x,(lab,val) in zip(xs,vals):
        rect(x,625,118,58); txt(x+9,662,lab,7.5,True); txt(x+9,641,str(val),10.5,True)
    txt(42,588,"GASTOS POR PLACA",12,True); line(42,580,553,580)
    y=558
    for _,r in por_placa.head(14).iterrows():
        txt(48,y,str(r["placa"]),9,True); txt(420,y,dinheiro(r["valor"]),9,True); line(48,y-6,540,y-6,.25); y-=21
    if len(por_placa)>14: txt(48,y,f"+ {len(por_placa)-14} placa(s) no Excel",8)
    line(42,52,553,52,.4); txt(42,35,f"Gerado em {datetime.now().strftime('%d/%m/%Y %H:%M')}",7.5); txt(470,35,"GDS",8,True)
    stream="\n".join(cmds).encode("latin-1",errors="replace")
    objs=[
        b"<< /Type /Catalog /Pages 2 0 R >>",
        b"<< /Type /Pages /Kids [3 0 R] /Count 1 >>",
        b"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> >> /Contents 4 0 R >>",
        f"<< /Length {len(stream)} >>\nstream\n".encode()+stream+b"\nendstream",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
        b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>",
    ]
    out=bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n"); offs=[0]
    for i,o in enumerate(objs,1):
        offs.append(len(out)); out.extend(f"{i} 0 obj\n".encode()); out.extend(o); out.extend(b"\nendobj\n")
    xref=len(out); out.extend(f"xref\n0 {len(objs)+1}\n".encode()); out.extend(b"0000000000 65535 f \n")
    for off in offs[1:]: out.extend(f"{off:010d} 00000 n \n".encode())
    out.extend(f"trailer\n<< /Size {len(objs)+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF".encode())
    return bytes(out)

