# BASE ORIGINAL EMBUTIDA
# =========================================================
def base_original_df():
    data=base64.b64decode(BASE_XLSX_B64)
    xls=pd.ExcelFile(BytesIO(data))
    aba="2025" if "2025" in xls.sheet_names else xls.sheet_names[0]
    df=pd.read_excel(BytesIO(data),sheet_name=aba)
    df.columns=[str(c).strip() for c in df.columns]
    mapa={
        "PLACA":"placa","DATA":"data","NUM RECIBO/NF":"nf_recibo",
        "CNPJ REMETENTE":"cnpj_fornecedor","NOME REMETENTE":"nome_fornecedor",
        "PRODUTO/SERVIÇO":"produto_servico","QTD":"quantidade",
        "VALOR UNITARIO":"valor","OBS":"observacao"
    }
    df=df.rename(columns=mapa)
    regs=[]
    seq=1
    for _,r in df.iterrows():
        placa=normaliza_placa(r.get("placa"))
        dt=pd.to_datetime(r.get("data"),errors="coerce")
        if not placa or placa=="NAN" or pd.isna(dt): continue
        valor_bruto=r.get("valor")
        obs="" if pd.isna(r.get("observacao")) else str(r.get("observacao")).strip()
        if isinstance(valor_bruto,str) and valor_bruto.strip() and not re.search(r"\d",valor_bruto):
            obs=(obs+" | " if obs else "")+"VALOR ORIGINAL NA PLANILHA: "+valor_bruto.strip()
        serv="" if pd.isna(r.get("produto_servico")) else str(r.get("produto_servico")).strip()
        qtd=r.get("quantidade")
        try: qtd=None if pd.isna(qtd) else float(qtd)
        except: qtd=None
        regs.append({
            "id":seq,"placa":placa,"data":dt.date().isoformat(),
            "nf_recibo":"" if pd.isna(r.get("nf_recibo")) else str(r.get("nf_recibo")).strip(),
            "cnpj_fornecedor":normaliza_cnpj(r.get("cnpj_fornecedor")),
            "nome_fornecedor":"" if pd.isna(r.get("nome_fornecedor")) else str(r.get("nome_fornecedor")).strip().upper(),
            "tipo_manutencao":tipo_automatico(serv),
            "produto_servico":serv,"quantidade":qtd,"valor":parse_valor(valor_bruto),
            "observacao":obs,"criado_em":datetime.now().isoformat(timespec="seconds"),"origem":"BASE INICIAL"
        })
        seq+=1
    return pd.DataFrame(regs)

