def github_cfg():
    try:
        token=st.secrets.get("GITHUB_TOKEN","")
        repo=st.secrets.get("GITHUB_REPO","")
        branch=st.secrets.get("GITHUB_DATA_BRANCH","main")
        path=st.secrets.get("GITHUB_DB_PATH","data/manutencao_gds.json")
        if token and repo: return token,repo,branch,path
    except: pass
    return None

def gh_headers(token):
    return {"Authorization":f"Bearer {token}","Accept":"application/vnd.github+json","X-GitHub-Api-Version":"2022-11-28"}

def gh_load():
    cfg=github_cfg()
    if not cfg: return None
    token,repo,branch,path=cfg
    url=f"https://api.github.com/repos/{repo}/contents/{path}"
    r=requests.get(url,headers=gh_headers(token),params={"ref":branch},timeout=20)
    if r.status_code==404: return None
    r.raise_for_status()
    obj=r.json()
    content=base64.b64decode(obj["content"]).decode("utf-8")
    payload=json.loads(content)
    return payload.get("registros",[])

def gh_save(records):
    token,repo,branch,path=github_cfg()
    url=f"https://api.github.com/repos/{repo}/contents/{path}"
    headers=gh_headers(token)
    get=requests.get(url,headers=headers,params={"ref":branch},timeout=20)
    sha=get.json().get("sha") if get.status_code==200 else None
    payload={
        "versao":1,
        "atualizado_em":datetime.now().isoformat(timespec="seconds"),
        "registros":records,
    }
    body={
        "message":"Atualiza base de manutenção GDS",
        "content":base64.b64encode(json.dumps(payload,ensure_ascii=False,indent=2).encode()).decode(),
        "branch":branch,
    }
    if sha: body["sha"]=sha
    put=requests.put(url,headers=headers,json=body,timeout=30)
    put.raise_for_status()

def local_init():
    with sqlite3.connect(DB_PATH) as c:
        c.execute("""CREATE TABLE IF NOT EXISTS manutencoes(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            placa TEXT NOT NULL, data TEXT NOT NULL, nf_recibo TEXT,
            cnpj_fornecedor TEXT, nome_fornecedor TEXT, produto_servico TEXT,
            quantidade REAL, valor REAL NOT NULL DEFAULT 0, observacao TEXT,
            criado_em TEXT NOT NULL, origem TEXT DEFAULT 'APP'
        )""")
        cols=[r[1] for r in c.execute("PRAGMA table_info(manutencoes)").fetchall()]
        if "tipo_manutencao" not in cols:
            c.execute("ALTER TABLE manutencoes ADD COLUMN tipo_manutencao TEXT")
        c.commit()
        n=c.execute("SELECT COUNT(*) FROM manutencoes").fetchone()[0]
        if n==0:
            base=base_original_df()
            for _,r in base.iterrows():
                c.execute("""INSERT INTO manutencoes
                (placa,data,nf_recibo,cnpj_fornecedor,nome_fornecedor,tipo_manutencao,produto_servico,quantidade,valor,observacao,criado_em,origem)
                VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",
                (r.placa,r.data,r.nf_recibo,r.cnpj_fornecedor,r.nome_fornecedor,r.tipo_manutencao,
                 r.produto_servico,r.quantidade,r.valor,r.observacao,r.criado_em,r.origem))
            c.commit()
        # preenche tipo faltante em banco antigo sem alterar demais campos
        rows=c.execute("SELECT id,produto_servico,tipo_manutencao FROM manutencoes").fetchall()
        for rid,serv,tipo in rows:
            if not tipo:
                c.execute("UPDATE manutencoes SET tipo_manutencao=? WHERE id=?",(tipo_automatico(serv),rid))
        c.commit()

def load_records():
    cfg=github_cfg()
    if cfg:
        try:
            regs=gh_load()
            if regs is None:
                regs=base_original_df().to_dict("records")
                gh_save(regs)
            return regs
        except Exception as e:
            st.error(f"Não foi possível acessar o banco online: {e}")
            st.stop()
    local_init()
    with sqlite3.connect(DB_PATH) as c:
        df=pd.read_sql_query("SELECT * FROM manutencoes ORDER BY date(data) DESC,id DESC",c)
    return df.to_dict("records")

def save_records(records):
    if github_cfg():
        gh_save(records); return
    local_init()
    with sqlite3.connect(DB_PATH) as c:
        c.execute("DELETE FROM manutencoes")
        for r in records:
            c.execute("""INSERT INTO manutencoes
            (id,placa,data,nf_recibo,cnpj_fornecedor,nome_fornecedor,tipo_manutencao,produto_servico,quantidade,valor,observacao,criado_em,origem)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (int(r["id"]),r["placa"],r["data"],r.get("nf_recibo",""),r.get("cnpj_fornecedor",""),
             r.get("nome_fornecedor",""),r.get("tipo_manutencao","Outros"),r.get("produto_servico",""),
             r.get("quantidade"),float(r.get("valor",0) or 0),r.get("observacao",""),
             r.get("criado_em",""),r.get("origem","APP")))
        c.commit()

def df_records():
    df=pd.DataFrame(load_records())
    if df.empty:
        return pd.DataFrame(columns=["id","placa","data","nf_recibo","cnpj_fornecedor","nome_fornecedor",
            "tipo_manutencao","produto_servico","quantidade","valor","observacao","criado_em","origem","data_dt"])
    for c in ["id","placa","data","nf_recibo","cnpj_fornecedor","nome_fornecedor","tipo_manutencao",
              "produto_servico","quantidade","valor","observacao","criado_em","origem"]:
        if c not in df: df[c]=""
    df["data_dt"]=pd.to_datetime(df["data"],errors="coerce")
    df["valor"]=pd.to_numeric(df["valor"],errors="coerce").fillna(0)
    return df.sort_values(["data_dt","id"],ascending=[False,False]).reset_index(drop=True)

def supplier_name(cnpj, df):
    c=normaliza_cnpj(cnpj)
    if not c or df.empty: return ""
    m=df[df["cnpj_fornecedor"].astype(str)==c]
    if m.empty: return ""
    return str(m.iloc[0]["nome_fornecedor"] or "")

def next_id(records):
    ids=[int(r.get("id",0) or 0) for r in records]
    return max(ids,default=0)+1

def record_from_row(r):
    return {k:(None if pd.isna(v) else v) for k,v in r.items() if k!="data_dt"}

